(x, y, t) => {
  const cx = 240, cy = 120;
  const primes = [2, 3, 5, 7, 11, 13];
  const wx = Math.sin(x * 0.02 + t * 0.3) * 12 + Math.cos(y * 0.015 - t * 0.2) * 8;
  const wy = Math.cos(y * 0.02 - t * 0.25) * 12 + Math.sin(x * 0.018 + t * 0.35) * 8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08*primes[0], 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1*primes[1]/3, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06*primes[2]/5, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12*primes[3]/7, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07*primes[4]/11, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09*primes[5]/13, 1.9],
    [80+Math.sin(t*0.45)*60, 40+Math.cos(t*0.65)*40, 0.11, 2.1],
    [400+Math.cos(t*0.55+3)*70, 200+Math.sin(t*0.75+1)*50, 0.085, 1.8]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  const act = aS/8, inh = iS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.5);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const gridX = Math.abs(Math.sin(sx * Math.PI / primes[2])) < 0.03 ? 0.15 : 0;
  const gridY = Math.abs(Math.sin(sy * Math.PI / primes[3])) < 0.03 ? 0.15 : 0;
  const neuralGrid = gridX + gridY;
  const layerLines = [];
  for (let p = 0; p < 6; p++) {
    const ly = 20 + p * 38 + Math.sin(t * 0.4 + p) * 3;
    const lw = 180 + Math.sin(t * 0.3 + p * 1.7) * 60;
    const lx = 30 + Math.cos(t * 0.2 + p * 2.3) * 40;
    const inLayer = sx > lx && sx < lx + lw && Math.abs(sy - ly) < 1.2;
    const barW = lw * (0.3 + 0.4 * Math.abs(Math.sin(t * 0.5 + p * primes[p % 6])));
    const inBar = sx > lx && sx < lx + barW && Math.abs(sy - ly) < 0.8;
    layerLines.push(inLayer ? 0.08 : 0);
    layerLines.push(inBar ? 0.25 : 0);
  }
  const uiLayer = layerLines.reduce((a, b) => a + b, 0);
  const primeNodes = [];
  for (let i = 0; i < 6; i++) {
    const px = 40 + i * 80 + Math.sin(t * 0.3 + i * primes[i]) * 15;
    const py = 220 + Math.cos(t * 0.4 + i * 1.3) * 8;
    const pd = Math.sqrt((sx - px) ** 2 + (sy - py) ** 2);
    const pulse = Math.sin(t * 2 + i * primes[i] * 0.5) * 0.5 + 0.5;
    primeNodes.push(pd < 4 + pulse * 3 ? 0.35 * pulse : 0);
    if (i < 5) {
      const nx = 40 + (i + 1) * 80 + Math.sin(t * 0.3 + (i + 1) * primes[i + 1]) * 15;
      const ny = 220 + Math.cos(t * 0.4 + (i + 1) * 1.3) * 8;
      const lineDist = Math.abs((ny - py) * (sx - px) - (nx - px) * (sy - py)) / Math.sqrt((nx - px) ** 2 + (ny - py) ** 2);
      primeNodes.push(lineDist < 0.8 ? 0.12 : 0);
    }
  }
  const nodeLayer = primeNodes.reduce((a, b) => a + b, 0);
  const scanline = Math.sin(sy * Math.PI * 2 + t * 3) > 0.97 ? 0.06 : 0;
  const blend = reaction * 0.6 + cell * 0.15 + neuralGrid * 0.08 + uiLayer * 0.1 + nodeLayer * 0.12 + scanline;
  const v = Math.max(0, Math.min(1, blend * 0.5 + 0.5));
  const pal = [
    [5, 2, 30], [20, 10, 80], [0, 60, 120], [0, 180, 160],
    [50, 255, 200], [180, 255, 100], [255, 220, 50], [255, 100, 80],
    [255, 50, 150], [200, 30, 255], [100, 10, 180], [5, 2, 30]
  ];
  const idx = v * (pal.length - 1), i = Math.min(idx | 0, pal.length - 2), f = idx - i;
  const lum = 0.7 + Math.sin(reaction * Math.PI) * 0.3;
  const neon = Math.abs(reaction) > 0.6 ? 1.4 : (Math.abs(reaction) > 0.3 ? 1.1 : 0.85);
  const boost = (uiLayer + nodeLayer) > 0.1 ? 1.2 : 1.0;
  return [
    Math.min(255, (pal[i][0] + (pal[i + 1][0] - pal[i][0]) * f) * lum * neon * boost) | 0,
    Math.min(255, (pal[i][1] + (pal[i + 1][1] - pal[i][1]) * f) * lum * neon * boost) | 0,
    Math.min(255, (pal[i][2] + (pal[i + 1][2] - pal[i][2]) * f) * lum * neon * boost) | 0
  ];
}
